}

// MT2009_PLUS_RARE_MOB_RULES_V1 (cor): the mob's own Cor chance and count.
const Mt2009PlusRareMobRule* rareRule = Mt2009PlusRareMobRuleFor(pkChr);
if (rareRule)
{
	corChance = rareRule->corChance;
	corKind = "rule";
}

int szarfaChance = pkChr->IsStone() ? 15 : 80;
// MT2009_PLUS_RARE_MOB_RULES_V1 (sash): the mob's own sash chance.
if (const Mt2009PlusRareMobRule* sashRule = Mt2009PlusRareMobRuleFor(pkChr))
	szarfaChance = sashRule->sashChance;

// MT2009_PLUS_DT_DROPS_V1 (server-patches/raremobrules): the Demon Tower (map 66, the ground
// floor, and its instances 660000-669999) drops for a player at the full rate whatever the
// level difference (the owner, 5 October: a level 75 got no upgrade items there and never the
// Biologist's Pamiatka po Demonie). aiPercentByDeltaLev pays 1% from fifteen levels over the
// monster: the tower's demons 1001-1004 (levels 57-60; the upgrade items 30015, 30087, 30016
// and 30086 through mob_proto's drop_item) and its stones 8015-8017 (50-60) rolled every
// table at 1% for a level 75, the Pamiatka (0.315% a kill) at 1 in 31 746 kills. The
// level-limit groups never faded, and the Cor / sash / book rules (rarelevel) stay as they
// are. A bot keeps the old fade (its tower raids, playerbot_demon_tower.h, are many and
// bring their loot to the market).
static bool Mt2009PlusDemonTowerFullDrop(LPCHARACTER pkKiller)
{
	if (!pkKiller || !pkKiller->IsPC() || !pkKiller->GetDesc() || pkKiller->GetDesc()->IsBot())
		return false;
	const long mapIndex = pkKiller->GetMapIndex();
	return mapIndex == 66 || (mapIndex >= 660000 && mapIndex < 670000);
}

