// MT2009_PLUS_DT_DROPS_V1 (delta): no level fade in the Demon Tower for a player.
if (iDeltaPercent < 100 && Mt2009PlusDemonTowerFullDrop(pkKiller))
	iDeltaPercent = 100;

sys_log(3, "CreateDropItem for level: %d rank: %u pct: %d", iLevel, bMobRank, iDeltaPercent);
